UPDATE cms_documents SET published=json_insert(published,(SELECT fullkey || '.items[#]' FROM json_each(published) WHERE json_extract(value,'$.id')='album-once-human'),json('{"name":"11-new-home-with-a-friend.png","url":"/galleries/Once%20Human/11-new-home-with-a-friend.png","id":"once-human-10","title":"11-new-home-with-a-friend.png","type":"image/png"}')), revision=revision+1 WHERE site='morteva' AND section='gallery' AND EXISTS(SELECT 1 FROM json_each(published) WHERE json_extract(value,'$.id')='album-once-human') AND NOT EXISTS(SELECT 1 FROM json_tree(published) WHERE key='id' AND value='once-human-10');
